action.mutation:
mutation CreateWorkcenterHistory($payload: [WorkcenterHistoryCreatePayloadInput!]!) {
  mutation: createWorkcenterHistory(payload: $payload) { 
    id
    number
  }
}

dataTransform.transform:
[edges.node~>|$|(


$d := occurAt;
$c := createdAt;
{
"duration": $not($isNilOrEmpty(duration)) ? duration 
: $isNilOrEmpty(duration) and $not($isNilOrEmpty(occurAt)) 
? $moment().diff($moment($d),'seconds') 
: $isNilOrEmpty(duration) and $isNilOrEmpty(occurAt)
? $moment().diff($moment($c),'seconds')
: 0,

"running": $isNilOrEmpty(endAt) ? "CURRENT"
: null,

"eventCategory": $isNilOrEmpty(event.eventCategory.id) ? "Undefined"
: event.eventCategory.name
}



)|]
